      const jumpBtns = this.container.querySelectorAll(".mem-jump-btn");
      jumpBtns.forEach((btn) => {
        btn.addEventListener("click", (e) => {
          e.preventDefault();
          const addrStr = btn.getAttribute("data-addr");
          if (addrStr) {
            applyAddr(addrStr);
          }
        });
      });
